    ('6d66a78e-0b9c-5257-ae17-9cb93155280f'::uuid, 'Quiz — Séquence, condition, boucle, variable', 'Technologie', '4e', 'Bases de la programmation', '631f0af7-6d5d-5874-8a7b-31dd2138d6d9'::uuid),
    ('1e568f9b-9059-5d45-a338-62f11544319e'::uuid, 'Quiz — Des blocs à assembler, ou des lignes à écrire', 'Technologie', '4e', 'Programmation graphique et programmation textuelle', 'be15c87d-6c48-585c-b074-74ccb48dfba7'::uuid),
    ('6bfd6eea-afa2-5af8-8569-c5789a1a9b71'::uuid, 'Quiz — Du besoin au programme qui marche', 'Technologie', '4e', 'Écrire mettre au point et exécuter un programme simple', '8d3aec37-54e7-5ee3-aad4-b9bb86da3b03'::uuid),
    ('2fc4609f-5f7d-5d8b-8240-20f7b081947a'::uuid, 'Quiz — Organiser pour pouvoir chercher', 'Technologie', '4e', 'Structuration et traitement des données', '45921280-47d2-506b-83fa-8105b55b2c39'::uuid),
    ('7d8eec64-79ae-5e66-8bca-184f7c2cb55e'::uuid, 'Quiz — Où vivent les données, et qui y a droit', 'Technologie', '4e', 'Système d’information et stockage de données', '67ae7c75-9137-5abd-bb7a-e537be644a6f'::uuid),
    ('02479358-a3cc-516f-8df9-4faf14c25c92'::uuid, 'Quiz — Comment un message va d’une machine à l’autre', 'Technologie', '4e', 'La circulation de l’information dans un réseau informatique', 'e8d3a072-53a2-51e4-ae4b-dc7029c410a6'::uuid),
    ('a361a3fa-ab75-5e04-bbd7-6cf0a2042d46'::uuid, 'Quiz — Des tâches, des délais, une équipe', 'Technologie', '4e', 'Organisation d’un projet technique', '4a25a36c-40de-5eb2-807a-8e922e6be9e9'::uuid),
    ('00feabf3-2c17-5a23-975f-c845aa78ca3a'::uuid, 'Quiz — Dessiner pour se faire comprendre', 'Technologie', '4e', 'Modes de représentation d’un OST', '59893996-9680-599d-8a03-c2390b010a2d'::uuid),
    ('4b158890-abe1-5226-bd1e-84e771f004e7'::uuid, 'Quiz — De l’idée à l’objet réel', 'Technologie', '4e', 'Concevoir et fabriquer un OST', '5bd284eb-7488-5d46-bded-3899591e84a4'::uuid),
    ('1daa75ee-9f07-578f-b265-ac2b92d29317'::uuid, 'Quiz — Prouver que l’objet fait ce qu’on a promis', 'Technologie', '4e', 'Tester et valider la tenue mécanique, le comportement et les performances d’un objet technique', 'fd98c12c-5ce0-509d-873a-814850d5be70'::uuid),
    ('101cfd87-5688-56ec-bcfe-2ec7896cbf68'::uuid, 'Quiz — Fabriquer pour apprendre, avant de fabriquer pour vendre', 'Technologie', '4e', 'Prototypage de solutions', '0a82aba9-dd5d-5fc1-b0b0-e169567255eb'::uuid)
  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
  JOIN public.lessons l ON l.id = v.lesson_id
 WHERE NOT EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.lesson_id = l.id)
ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('20e76934-8720-56cd-ba17-8458d7f18636'::uuid, 'e5f106de-8687-5b16-a6b1-c3588688baa0'::uuid, 'Que signifie le sigle OST ?', 'mcq', '["Objet et Système Technique","Organisation Standard du Travail","Outil de Simulation Technique","Objet Sans Transformation"]'::jsonb, 0, 'C’est le vocabulaire employé tout au long du programme.', 1),
    ('c23a46bc-97bd-5c97-b3ed-fc0a2ce23108'::uuid, 'e5f106de-8687-5b16-a6b1-c3588688baa0'::uuid, 'Qu’est-ce qui distingue un système technique d’un objet technique ?', 'mcq', '["Il associe plusieurs objets qui travaillent ensemble","Il est toujours plus grand","Il ne consomme pas d’énergie","Il n’a pas d’utilisateur"]'::jsonb, 0, 'Un ascenseur ou une alarme sont des systèmes.', 2),
    ('27b86bf3-2b7e-5e91-b84c-f528bd717a8d'::uuid, 'e5f106de-8687-5b16-a6b1-c3588688baa0'::uuid, 'À quelle question répond la fonction d’usage d’un objet ?', 'mcq', '["Dans quel but l’objet est-il utilisé ?","Combien coûte-t-il ?","De quel matériau est-il fait ?","Qui l’a inventé ?"]'::jsonb, 0, 'Elle complète « à qui rend-il service » et « sur quoi agit-il ».', 3),
    ('c880ee1a-2ddd-54b0-838a-e69c5543d019'::uuid, 'e5f106de-8687-5b16-a6b1-c3588688baa0'::uuid, 'Qu’est-ce qui fait évoluer un objet technique ?', 'mcq', '["Les besoins, le progrès technique, les contraintes économiques et environnementales","Uniquement la mode","Uniquement le prix des matériaux","Rien : un objet réussi ne change plus"]'::jsonb, 0, 'Ces quatre moteurs jouent ensemble.', 4),
    ('ea7604e4-c462-5f6b-aa2f-82ea57706a53'::uuid, 'e5f106de-8687-5b16-a6b1-c3588688baa0'::uuid, 'Qu’est-ce qu’une famille d’objets techniques ?', 'mcq', '["Des objets qui remplissent la même fonction d’usage par des solutions différentes","Des objets fabriqués par la même entreprise","Des objets vendus au même prix","Des objets du même matériau"]'::jsonb, 0, 'Bougie, lampe à huile, ampoule et LED forment une famille.', 5),
    ('8a2095d7-f21e-51af-814c-0fddc2861988'::uuid, 'e5f106de-8687-5b16-a6b1-c3588688baa0'::uuid, 'Qu’est-ce qu’une lignée d’objets techniques ?', 'mcq', '["Un objet suivi dans ses améliorations successives au fil du temps","Une gamme de produits d’une marque","Une chaîne de fabrication","Un classement par prix"]'::jsonb, 0, 'Elle raconte l’histoire d’un même objet.', 6),
    ('70cee357-8084-5ff6-b602-18f13d5ff425'::uuid, 'e5f106de-8687-5b16-a6b1-c3588688baa0'::uuid, 'Qu’est-ce qu’un besoin, en technologie ?', 'mcq', '["Ce qui justifie l’existence de l’objet technique","Le prix maximal accepté par l’acheteur","La quantité d’énergie consommée","Le nombre de pièces de l’objet"]'::jsonb, 0, 'Tout OST naît d’un besoin à satisfaire.', 7),
    ('2657c24a-3b09-5ac3-8363-178fc7dc5117'::uuid, 'e5f106de-8687-5b16-a6b1-c3588688baa0'::uuid, 'Un objet technique existe indépendamment de tout besoin humain.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est conçu et fabriqué précisément pour satisfaire un besoin.', 8),
    ('46625738-7a01-5ed5-ac71-c51412ce8046'::uuid, 'b697b454-0f0c-552f-aa64-78782bae91bb'::uuid, 'Qu’est-ce que la fonction d’usage d’un objet ?', 'mcq', '["Le service qu’il rend à l’utilisateur","Le phénomène physique qu’il exploite","Le composant qui le réalise","Son prix de revient"]'::jsonb, 0, 'Elle s’exprime par un verbe à l’infinitif.', 1),
    ('82fa4221-d220-51db-bcc1-b9ccb13c3227'::uuid, 'b697b454-0f0c-552f-aa64-78782bae91bb'::uuid, 'Qu’est-ce qu’une fonction technique ?', 'mcq', '["Ce que l’objet doit assurer en interne pour remplir sa fonction d’usage","Le service rendu à l’utilisateur","Le matériau employé","Le mode d’emploi"]'::jsonb, 0, 'Transmettre le mouvement, freiner, diriger, pour un vélo.', 2),
    ('61fdcc81-95c0-5638-be1b-efe6a3d9f004'::uuid, 'b697b454-0f0c-552f-aa64-78782bae91bb'::uuid, 'Qu’est-ce qu’un principe technique ?', 'mcq', '["Le phénomène physique utilisé pour réaliser une fonction","Le composant concret retenu","Le service rendu","La norme à respecter"]'::jsonb, 0, 'Le frottement pour freiner, l’électromagnétisme pour produire du courant.', 3),
    ('a9ac7ff7-d0c4-5773-967a-5083138e5b97'::uuid, 'b697b454-0f0c-552f-aa64-78782bae91bb'::uuid, 'Qu’est-ce qu’une solution technique ?', 'mcq', '["Le composant concret retenu pour réaliser une fonction","Le besoin de l’utilisateur","Le phénomène physique exploité","La durée de vie de l’objet"]'::jsonb, 0, 'Frein à patins ou frein à disque : deux solutions, un même principe.', 4),
    ('c18abdf6-1406-59cb-a61c-619d9d722a01'::uuid, 'b697b454-0f0c-552f-aa64-78782bae91bb'::uuid, 'Combien de solutions techniques une même fonction peut-elle avoir ?', 'mcq', '["Plusieurs","Une seule","Aucune","Autant que d’utilisateurs"]'::jsonb, 0, 'C’est ce qui rend la comparaison possible en conception.', 5),
    ('596cd0d2-c336-5002-94a8-ec277505bab8'::uuid, 'b697b454-0f0c-552f-aa64-78782bae91bb'::uuid, 'Qu’est-ce qui rend une exigence du cahier des charges vérifiable ?', 'mcq', '["Un critère mesurable et un niveau chiffré","Une description détaillée","Un dessin de l’objet","La signature du client"]'::jsonb, 0, 'Sans niveau chiffré, une exigence n’est qu’un vœu.', 6),
    ('69918de9-5c89-50c4-90cd-c1d9aa6aa96f'::uuid, 'b697b454-0f0c-552f-aa64-78782bae91bb'::uuid, 'Comment représente-t-on le lien entre fonctions et solutions ?', 'mcq', '["Par un diagramme ou un arbre des fonctions","Par un graphique en camembert","Par un chronogramme","Par une carte du réseau"]'::jsonb, 0, 'Fonction d’usage → fonctions techniques → solutions techniques.', 7),
    ('d5aadcb5-091b-5222-b551-a8abd2d1e7da'::uuid, 'b697b454-0f0c-552f-aa64-78782bae91bb'::uuid, 'Une fonction d’usage et une fonction technique désignent la même chose.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’une regarde l’utilisateur, l’autre l’intérieur de l’objet.', 8),
    ('49f0597e-c539-5f75-8de7-2e7808411735'::uuid, '59f0b5f7-364f-58f1-ac8f-413768bd5a41'::uuid, 'Quelle est la première étape du cycle de vie d’un objet ?', 'mcq', '["L’extraction des matières premières","La fabrication","La distribution","L’utilisation"]'::jsonb, 0, 'Le cycle commence bien avant l’usine.', 1),
    ('5b761ed9-1078-56a2-b2e0-22a1bc6d44ea'::uuid, '59f0b5f7-364f-58f1-ac8f-413768bd5a41'::uuid, 'Que mesure une analyse du cycle de vie (ACV) ?', 'mcq', '["Les impacts environnementaux de l’objet à toutes ses étapes","Le prix de vente de l’objet","La durée de la garantie","Le nombre de pièces de l’objet"]'::jsonb, 0, 'Elle permet de comparer deux objets sans se limiter à leur usage.', 2),
    ('865eb7ea-7f2c-53fd-ba5e-3cb3d4ece343'::uuid, '59f0b5f7-364f-58f1-ac8f-413768bd5a41'::uuid, 'Qu’est-ce que l’économie circulaire ?', 'mcq', '["Un modèle qui réduit, réemploie et recycle pour refermer la boucle","Un modèle qui produit toujours plus","Le commerce entre pays voisins","La vente d’objets d’occasion uniquement"]'::jsonb, 0, 'Elle s’oppose au modèle linéaire extraire-fabriquer-jeter.', 3),
    ('9af4347a-e05b-54df-9110-fab49ce2c150'::uuid, '59f0b5f7-364f-58f1-ac8f-413768bd5a41'::uuid, 'Que désignent les DEEE ?', 'mcq', '["Les déchets d’équipements électriques et électroniques","Les déchets d’emballages en entreprise","Les données d’économie énergétique","Les documents d’étude environnementale"]'::jsonb, 0, 'Ils se déposent en déchèterie ou en point de collecte.', 4),
    ('5e5821b1-64d4-5b2c-a934-74fb2b1cd2a0'::uuid, '59f0b5f7-364f-58f1-ac8f-413768bd5a41'::uuid, 'Quelle étape du cycle de vie consomme souvent le plus d’énergie pour un appareil électroménager ?', 'mcq', '["L’utilisation","La distribution","La fin de vie","L’emballage"]'::jsonb, 0, 'D’où l’importance des étiquettes énergie.', 5),
    ('58d564a4-a9fc-5435-9769-8f0abf7dfcbe'::uuid, '59f0b5f7-364f-58f1-ac8f-413768bd5a41'::uuid, 'Qu’est-ce que la valorisation énergétique d’un déchet ?', 'mcq', '["Récupérer de l’énergie en le brûlant","Le revendre d’occasion","Le broyer pour en faire une matière première","L’enfouir sous terre"]'::jsonb, 0, 'C’est une solution moins bonne que le recyclage, meilleure que l’enfouissement.', 6),
    ('6990b586-838b-53be-b584-5a10a2db8802'::uuid, '59f0b5f7-364f-58f1-ac8f-413768bd5a41'::uuid, 'Qu’est-ce que l’indice de réparabilité ?', 'mcq', '["Une note obligatoire indiquant si un produit est facile à réparer","Le nombre de réparations effectuées","La durée de la garantie légale","Le prix des pièces détachées"]'::jsonb, 0, 'Il lutte contre l’obsolescence en informant l’acheteur.', 7),
    ('178c6f3f-7361-5f6e-9171-ac1f336940fd'::uuid, '59f0b5f7-364f-58f1-ac8f-413768bd5a41'::uuid, 'Un objet non cassé ne peut pas devenir inutilisable.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’obsolescence logicielle ou l’absence de pièces détachées suffit à le rendre inutilisable.', 8),
    ('d9ec542d-c5ef-5cc8-ab94-4ac132b0ded4'::uuid, '02915ea1-509f-594a-992e-ba68a2d06958'::uuid, 'Qu’est-ce qu’un interacteur ?', 'mcq', '["Un élément de l’environnement en relation avec l’objet technique","Une pièce interne de l’objet","Un logiciel de conception","Un défaut de fabrication"]'::jsonb, 0, 'Utilisateur, énergie, milieu, normes, budget en sont.', 1),
    ('089e585d-b002-5f31-9bec-7c091e10c102'::uuid, '02915ea1-509f-594a-992e-ba68a2d06958'::uuid, 'Que relie une fonction principale dans un diagramme des interacteurs ?', 'mcq', '["Deux interacteurs à travers l’objet","L’objet à un seul interacteur","Deux objets entre eux","L’objet à son fabricant"]'::jsonb, 0, 'C’est la raison d’être de l’objet.', 2),
    ('866d4236-fed1-5d7a-b8c7-a42d0a9652b6'::uuid, '02915ea1-509f-594a-992e-ba68a2d06958'::uuid, 'Que relie une fonction contrainte ?', 'mcq', '["L’objet à un seul interacteur","Deux interacteurs entre eux","Deux fonctions principales","L’utilisateur au fabricant"]'::jsonb, 0, 'Résister à la pluie, respecter une norme, tenir dans un budget.', 3),
    ('7f2a55ad-7cc4-54cd-8e67-4d20b229e59f'::uuid, '02915ea1-509f-594a-992e-ba68a2d06958'::uuid, 'Quelle est la fonction principale d’un lampadaire de rue ?', 'mcq', '["Permettre au piéton de voir la chaussée la nuit","Résister aux intempéries","Respecter le budget de la commune","S’intégrer au paysage urbain"]'::jsonb, 0, 'Les trois autres propositions sont des fonctions contraintes.', 4),
    ('899e9c97-d909-5520-80a1-4a10a79f30bd'::uuid, '02915ea1-509f-594a-992e-ba68a2d06958'::uuid, 'Où place-t-on l’objet dans un diagramme des interacteurs ?', 'mcq', '["Au centre, les interacteurs autour","En haut, les interacteurs en dessous","À gauche, comme point de départ","À l’extérieur du diagramme"]'::jsonb, 0, 'Les liaisons partent de lui vers son environnement.', 5),
    ('9e61148b-f1f9-5166-8cbb-76081d5a44eb'::uuid, '02915ea1-509f-594a-992e-ba68a2d06958'::uuid, 'À quoi sert le diagramme des interacteurs ?', 'mcq', '["À établir le cahier des charges de l’objet","À dessiner l’objet en trois dimensions","À calculer son prix de revient","À programmer son microcontrôleur"]'::jsonb, 0, 'Chaque fonction identifiée devient une exigence à mesurer.', 6),
    ('15a12060-342e-574e-9337-16cf3e02392c'::uuid, '02915ea1-509f-594a-992e-ba68a2d06958'::uuid, 'Qu’appelle-t-on la matière d’œuvre d’un objet technique ?', 'mcq', '["Ce sur quoi l’objet agit","Le matériau dont il est fait","L’énergie qu’il consomme","L’outil qui l’a fabriqué"]'::jsonb, 0, 'Pour un sèche-cheveux, ce sont les cheveux, pas le plastique du boîtier.', 7),
    ('6394176d-ae32-5bea-9092-207a39689070'::uuid, '02915ea1-509f-594a-992e-ba68a2d06958'::uuid, 'Un objet qui remplit sa fonction principale remplit forcément son cahier des charges.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il doit aussi satisfaire toutes ses fonctions contraintes.', 8),
    ('3a7770b4-284d-5669-8059-154465062716'::uuid, '86dc1510-5d83-5cf8-bca9-720e33efc4da'::uuid, 'Qu’est-ce qu’une contrainte, en technologie ?', 'mcq', '["Une exigence imposée au concepteur, qui limite ses choix","Un défaut de l’objet","Une panne en cours d’usage","Le prix de vente conseillé"]'::jsonb, 0, 'Elle doit être respectée par la solution retenue.', 1),
    ('110a01cb-43de-54e1-885b-1ac2acb8563d'::uuid, '86dc1510-5d83-5cf8-bca9-720e33efc4da'::uuid, 'Quel document rassemble toutes les exigences d’un projet ?', 'mcq', '["Le cahier des charges fonctionnel","La notice d’utilisation","Le plan de fabrication","Le devis"]'::jsonb, 0, 'Chaque fonction y porte un critère, un niveau et une flexibilité.', 2),
    ('e4ae176e-2403-56d0-b72f-62bd4ce56ebd'::uuid, '86dc1510-5d83-5cf8-bca9-720e33efc4da'::uuid, 'Que doit comporter une exigence bien rédigée ?', 'mcq', '["Un critère mesurable et un niveau chiffré","Un adjectif qualificatif","Un dessin","Le nom du fabricant"]'::jsonb, 0, '« Masse inférieure à 300 g » plutôt que « le plus léger possible ».', 3),
    ('7b4858cd-b90f-5b70-bc08-6eb19d352004'::uuid, '86dc1510-5d83-5cf8-bca9-720e33efc4da'::uuid, 'À quelle famille appartient la contrainte « respecter la norme CE » ?', 'mcq', '["Aux contraintes réglementaires et normatives","Aux contraintes esthétiques","Aux contraintes ergonomiques","Aux contraintes économiques"]'::jsonb, 0, 'Les normes s’imposent au concepteur.', 4),
    ('cb3726aa-e86f-5e1c-9ea8-2ac069c13f3a'::uuid, '86dc1510-5d83-5cf8-bca9-720e33efc4da'::uuid, 'À quelle famille appartient la contrainte « être utilisable par une personne en fauteuil » ?', 'mcq', '["Aux contraintes ergonomiques","Aux contraintes économiques","Aux contraintes techniques","Aux contraintes esthétiques"]'::jsonb, 0, 'L’accessibilité relève du confort et de l’usage.', 5),
    ('6a251e51-795a-54c6-b030-aac7fac78ab8'::uuid, '86dc1510-5d83-5cf8-bca9-720e33efc4da'::uuid, 'Que signifie la flexibilité d’une exigence ?', 'mcq', '["La tolérance acceptée sur le niveau à atteindre","La souplesse du matériau","La durée de la garantie","Le nombre de solutions possibles"]'::jsonb, 0, 'F0 impératif, F1 peu négociable, F2 négociable.', 6),
    ('53e35aaf-d2ef-5e47-a730-ce3cfff311a7'::uuid, '86dc1510-5d83-5cf8-bca9-720e33efc4da'::uuid, 'Pourquoi concevoir suppose-t-il d’arbitrer ?', 'mcq', '["Parce que certaines contraintes s’opposent entre elles","Parce que le client change d’avis","Parce que les normes évoluent chaque année","Parce que les matériaux manquent toujours"]'::jsonb, 0, 'Alléger un objet le rend souvent moins résistant ou plus cher.', 7),
    ('ebfa26ef-2236-5832-ad7f-245c88614b8d'::uuid, '86dc1510-5d83-5cf8-bca9-720e33efc4da'::uuid, 'Une contrainte peut être vérifiée même si elle n’est pas mesurable.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Sans critère chiffré, aucun essai ne peut conclure.', 8),
    ('c8325b74-6750-506f-b106-87c89566ff3d'::uuid, '7fd98749-9c79-5681-915d-9b38058d96a8'::uuid, 'Quel outil sert à comparer plusieurs solutions techniques ?', 'mcq', '["Un tableau multicritère","Un diagramme des interacteurs","Un chronogramme","Un schéma de câblage"]'::jsonb, 0, 'Solutions en colonnes, critères en lignes.', 1),
    ('372d4c44-a33e-5aa3-b866-983a53f03632'::uuid, '7fd98749-9c79-5681-915d-9b38058d96a8'::uuid, 'À quoi sert la pondération dans un tableau comparatif ?', 'mcq', '["À donner plus de poids aux critères les plus importants","À augmenter le nombre de solutions","À réduire le nombre de critères","À calculer le prix de vente"]'::jsonb, 0, 'Sans elle, prix et sécurité pèseraient autant.', 2),
    ('b05addfc-75d8-571c-852b-4ca41db97778'::uuid, '7fd98749-9c79-5681-915d-9b38058d96a8'::uuid, 'Qu’est-ce que le coût global d’un objet ?', 'mcq', '["Le prix d’achat plus les coûts d’usage et d’entretien","Le prix d’achat seul","Le coût de fabrication","Le coût de recyclage"]'::jsonb, 0, 'Une LED chère à l’achat revient moins cher sur sa durée de vie.', 3),
    ('8518fad6-70ec-5b30-9661-3e25cfc47e26'::uuid, '7fd98749-9c79-5681-915d-9b38058d96a8'::uuid, 'Comment justifie-t-on correctement un choix technique ?', 'mcq', '["En le confrontant aux exigences du cahier des charges","En invoquant le goût du concepteur","En choisissant la solution la moins chère","En prenant la solution la plus récente"]'::jsonb, 0, 'Les critères impératifs (F0) départagent d’abord.', 4),
    ('85bb5f99-2f21-594e-8b14-e7780b2adf69'::uuid, '7fd98749-9c79-5681-915d-9b38058d96a8'::uuid, 'Quel critère mesure le temps de fonctionnement sans panne ?', 'mcq', '["La fiabilité","L’ergonomie","L’encombrement","L’esthétique"]'::jsonb, 0, 'Elle est souvent liée à la durée de vie annoncée.', 5),
    ('8146e069-7bb2-5f90-b51c-f2f46eabdd24'::uuid, '7fd98749-9c79-5681-915d-9b38058d96a8'::uuid, 'Pourquoi la réparabilité est-elle devenue un critère de choix ?', 'mcq', '["Parce qu’elle allonge la durée de vie et réduit les déchets","Parce qu’elle diminue le prix d’achat","Parce qu’elle accélère la fabrication","Parce qu’elle améliore l’esthétique"]'::jsonb, 0, 'Un indice de réparabilité est désormais obligatoire sur plusieurs familles de produits.', 6),
    ('b06371c1-a3c4-5809-848e-1944f735aa1e'::uuid, '7fd98749-9c79-5681-915d-9b38058d96a8'::uuid, 'Quel critère relève de l’impact environnemental ?', 'mcq', '["La recyclabilité des matériaux","Le confort d’utilisation","La rapidité de fabrication","Le style du produit"]'::jsonb, 0, 'Consommation d’énergie et matériaux employés en relèvent aussi.', 7),
    ('9579a1de-b572-55ee-bee5-1caeb02e0910'::uuid, '7fd98749-9c79-5681-915d-9b38058d96a8'::uuid, 'La solution la moins chère à l’achat est toujours la plus économique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le coût global inclut l’énergie, les consommables et l’entretien.', 8),
    ('10f4ea97-2b6c-50ad-a56d-79b22200bdfb'::uuid, 'dc574b10-fea5-58ca-9a02-66e938a919fa'::uuid, 'Quelles sont les quatre fonctions de la chaîne d’énergie, dans l’ordre ?', 'mcq', '["Alimenter, distribuer, convertir, transmettre","Acquérir, traiter, communiquer, agir","Convertir, alimenter, transmettre, distribuer","Alimenter, convertir, distribuer, agir"]'::jsonb, 0, 'Elle se termine par l’action produite.', 1),
    ('b1f78fad-0989-5e71-860c-635ba7b6b91d'::uuid, 'dc574b10-fea5-58ca-9a02-66e938a919fa'::uuid, 'Quelle fonction assure un interrupteur ou un relais ?', 'mcq', '["Distribuer","Alimenter","Convertir","Transmettre"]'::jsonb, 0, 'Ils laissent passer ou interrompent l’énergie.', 2),
    ('31be477b-0345-5a2e-a109-b8d2789e953b'::uuid, 'dc574b10-fea5-58ca-9a02-66e938a919fa'::uuid, 'Quelle fonction assure un moteur électrique ?', 'mcq', '["Convertir","Alimenter","Distribuer","Transmettre"]'::jsonb, 0, 'Il transforme l’énergie électrique en énergie mécanique.', 3),
    ('e0806659-f064-5992-914a-0d02b4e59eed'::uuid, 'dc574b10-fea5-58ca-9a02-66e938a919fa'::uuid, 'Comment appelle-t-on les composants qui convertissent l’énergie ?', 'mcq', '["Les actionneurs","Les capteurs","Les interfaces","Les protocoles"]'::jsonb, 0, 'Moteur, vérin, lampe, résistance chauffante.', 4),
    ('accc546d-4399-534d-8629-afdffd6f5bb4'::uuid, 'dc574b10-fea5-58ca-9a02-66e938a919fa'::uuid, 'Quelle fonction assurent des engrenages ou une courroie ?', 'mcq', '["Transmettre","Convertir","Alimenter","Distribuer"]'::jsonb, 0, 'Ils acheminent l’énergie mécanique en adaptant vitesse et effort.', 5),
    ('5a8cc48a-dc33-5363-b715-fda8e0bf0f21'::uuid, 'dc574b10-fea5-58ca-9a02-66e938a919fa'::uuid, 'Quelle source d’énergie assure la fonction « alimenter » d’un objet nomade ?', 'mcq', '["Une batterie","Un engrenage","Un relais","Un capteur"]'::jsonb, 0, 'Pile, batterie ou panneau solaire selon les cas.', 6),
    ('a6caf093-612e-5aae-8552-882bc80da7eb'::uuid, 'dc574b10-fea5-58ca-9a02-66e938a919fa'::uuid, 'Où les chaînes d’énergie et d’information se rejoignent-elles ?', 'mcq', '["À la fonction « distribuer », qui reçoit l’ordre de la partie commande","À la fonction « alimenter »","À la fonction « transmettre »","Elles ne se rejoignent jamais"]'::jsonb, 0, 'La chaîne d’information décide, la chaîne d’énergie agit.', 7),
    ('8ac55846-7e66-5539-b726-d6e3e6597a49'::uuid, 'dc574b10-fea5-58ca-9a02-66e938a919fa'::uuid, 'Un vérin pneumatique appartient à la fonction « transmettre ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un actionneur : il convertit l’énergie pneumatique en énergie mécanique.', 8),
    ('02f1815e-4b0d-5944-bfd2-c9f0ed1cbb6e'::uuid, '42f66987-462b-5266-9586-e5c69b041120'::uuid, 'Quelle différence y a-t-il entre transmettre et transformer un mouvement ?', 'mcq', '["Transmettre conserve la nature du mouvement, transformer la change","Transmettre change la nature, transformer conserve la vitesse","Ce sont deux mots pour la même chose","Transmettre concerne l’électricité, transformer la mécanique"]'::jsonb, 0, 'Rotation vers rotation, ou rotation vers translation.', 1),
    ('90b914d1-adeb-55bb-a391-8277439fefc4'::uuid, '42f66987-462b-5266-9586-e5c69b041120'::uuid, 'Dans quel sens tournent deux roues dentées en contact ?', 'mcq', '["En sens inverse l’une de l’autre","Dans le même sens","Elles ne tournent pas","Cela dépend de leur diamètre"]'::jsonb, 0, 'Sauf avec une roue intermédiaire ou un engrenage intérieur.', 2),
    ('35632c8d-0e07-54a0-b207-915baba45176'::uuid, '42f66987-462b-5266-9586-e5c69b041120'::uuid, 'Quel système de transmission n’a aucun risque de glissement ?', 'mcq', '["Pignons et chaîne","Poulies et courroie","Roues de friction","Courroie croisée"]'::jsonb, 0, 'C’est la transmission du vélo.', 3),
    ('d3bb9a01-850f-5c45-8735-6b2e147e6096'::uuid, '42f66987-462b-5266-9586-e5c69b041120'::uuid, 'Comment calcule-t-on le rapport de transmission ?', 'mcq', '["Vitesse de sortie ÷ vitesse d’entrée","Vitesse d’entrée × vitesse de sortie","Nombre de dents de sortie × vitesse d’entrée","Diamètre de sortie + diamètre d’entrée"]'::jsonb, 0, 'Il vaut aussi le nombre de dents de l’entrée divisé par celui de la sortie.', 4),
    ('ead1e47e-444c-581e-9038-afb6665a5205'::uuid, '42f66987-462b-5266-9586-e5c69b041120'::uuid, 'Que fait un réducteur ?', 'mcq', '["Il diminue la vitesse et augmente la force","Il augmente la vitesse et diminue la force","Il inverse le sens du mouvement","Il transforme la rotation en translation"]'::jsonb, 0, 'Son rapport de transmission est inférieur à 1.', 5),
    ('ae15d7aa-2248-5e55-8f06-3b6d0dd6b133'::uuid, '42f66987-462b-5266-9586-e5c69b041120'::uuid, 'Quel système transforme une rotation en translation ?', 'mcq', '["Le pignon-crémaillère","Les poulies-courroie","Les pignons-chaîne","Les roues de friction"]'::jsonb, 0, 'Le système vis-écrou et la bielle-manivelle aussi.', 6),
    ('d3e971e4-4b88-5651-89d6-b6865ae15798'::uuid, '42f66987-462b-5266-9586-e5c69b041120'::uuid, 'Quel système équipe un moteur thermique pour transformer le mouvement des pistons ?', 'mcq', '["La bielle-manivelle","Le pignon-crémaillère","La vis sans fin","La courroie croisée"]'::jsonb, 0, 'Il convertit la translation alternative en rotation.', 7),
    ('626f06f6-5565-50e7-8b34-e52e87c1229f'::uuid, '42f66987-462b-5266-9586-e5c69b041120'::uuid, 'Une transmission par courroie ne peut jamais glisser.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le glissement est justement son principal inconvénient face à la chaîne.', 8),
    ('63b681f2-b801-5a0e-a39b-3dcb730149ef'::uuid, 'ae530cd0-484e-5572-aea8-a705e0749a6f'::uuid, 'À quelle famille appartient le verre ?', 'mcq', '["Aux céramiques","Aux métalliques","Aux organiques","Aux composites"]'::jsonb, 0, 'Dur, résistant à la chaleur, mais fragile.', 1),
    ('2a9da645-2062-581c-9609-aee1dd2ffdb2'::uuid, 'ae530cd0-484e-5572-aea8-a705e0749a6f'::uuid, 'Qu’est-ce qu’un matériau composite ?', 'mcq', '["Un matériau associant deux matériaux pour cumuler leurs qualités","Un matériau recyclé","Un métal allié à un autre métal","Un plastique coloré"]'::jsonb, 0, 'Fibre de carbone dans une résine, béton armé, contreplaqué.', 2),
    ('56faaa6d-b222-5684-8ceb-df34c8a64745'::uuid, 'ae530cd0-484e-5572-aea8-a705e0749a6f'::uuid, 'Que mesure la dureté d’un matériau ?', 'mcq', '["Sa résistance à la rayure","Sa capacité à revenir à sa forme initiale","Sa masse par unité de volume","Sa conductivité électrique"]'::jsonb, 0, 'À ne pas confondre avec la résistance mécanique.', 3),
    ('376bd959-5fca-5700-9f5e-3e7ec9cc23a5'::uuid, 'ae530cd0-484e-5572-aea8-a705e0749a6f'::uuid, 'Que signifie l’élasticité d’un matériau ?', 'mcq', '["Il reprend sa forme après déformation","Il se raye difficilement","Il conduit bien la chaleur","Il résiste à la corrosion"]'::jsonb, 0, 'Au-delà d’une limite, la déformation devient permanente.', 4),
    ('4d8284d6-8486-5ae7-b2f3-d5df2e75fba3'::uuid, 'ae530cd0-484e-5572-aea8-a705e0749a6f'::uuid, 'Quelle propriété décide de la légèreté d’une pièce ?', 'mcq', '["La masse volumique du matériau","Sa dureté","Sa conductivité","Son élasticité"]'::jsonb, 0, 'C’est la masse par unité de volume.', 5),
    ('27f32ee4-e726-582a-9b36-0bae5e56fc08'::uuid, 'ae530cd0-484e-5572-aea8-a705e0749a6f'::uuid, 'Quel procédé convient à un thermoplastique ?', 'mcq', '["L’injection","Le soudage à l’arc","Le forgeage","Le sciage à la scie à métaux"]'::jsonb, 0, 'Extrusion, thermoformage et impression 3D également.', 6),
    ('b6edee02-38fc-5bea-80d2-8d5a20c49030'::uuid, 'ae530cd0-484e-5572-aea8-a705e0749a6f'::uuid, 'Quel avantage environnemental présente l’aluminium ?', 'mcq', '["Il se recycle presque indéfiniment","Il ne consomme pas d’énergie à produire","Il se dégrade naturellement","Il ne nécessite aucune extraction"]'::jsonb, 0, 'Sa production initiale reste, elle, très énergivore.', 7),
    ('f67d1b5b-3b12-539f-b505-482460963761'::uuid, 'ae530cd0-484e-5572-aea8-a705e0749a6f'::uuid, 'Il existe un matériau meilleur que tous les autres en toutes circonstances.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On choisit selon le profil de propriétés exigé par le cahier des charges.', 8),
    ('316d37ab-03ca-522d-8ced-9980b062e8e9'::uuid, '84a12868-f4fb-58cf-84b8-4d7ba000c215'::uuid, 'Quelles sont les trois fonctions de la chaîne d’information ?', 'mcq', '["Acquérir, traiter, communiquer","Alimenter, distribuer, convertir","Capter, convertir, agir","Mesurer, calculer, imprimer"]'::jsonb, 0, 'Capteurs, partie commande, moyens de communication.', 1),
    ('00b00bcf-9332-59cd-a974-a93aafbd5a01'::uuid, '84a12868-f4fb-58cf-84b8-4d7ba000c215'::uuid, 'À quelle fonction correspond un capteur ?', 'mcq', '["Acquérir","Traiter","Communiquer","Convertir"]'::jsonb, 0, 'Il recueille une information sur l’environnement ou le système.', 2),
    ('75774b5f-d98c-55c8-b29a-056fa744d4fa'::uuid, '84a12868-f4fb-58cf-84b8-4d7ba000c215'::uuid, 'Quel composant assure la fonction « traiter » ?', 'mcq', '["Le microcontrôleur","Le capteur de température","Le moteur","La LED"]'::jsonb, 0, 'Il exécute le programme et prend les décisions.', 3),
    ('72657ef6-f755-56b0-adb6-9b0372915e46'::uuid, '84a12868-f4fb-58cf-84b8-4d7ba000c215'::uuid, 'Quelle est la différence entre un capteur et un actionneur ?', 'mcq', '["Le capteur prend une information, l’actionneur produit une action","Le capteur produit une action, l’actionneur mesure","Ils appartiennent tous deux à la chaîne d’énergie","Ils font la même chose"]'::jsonb, 0, 'L’un est dans la chaîne d’information, l’autre dans la chaîne d’énergie.', 4),
    ('b7ee56e8-7ad6-5a49-853c-2c7ac52c46b2'::uuid, '84a12868-f4fb-58cf-84b8-4d7ba000c215'::uuid, 'À quelle fonction appartient un écran d’affichage ?', 'mcq', '["Communiquer","Acquérir","Traiter","Transmettre"]'::jsonb, 0, 'Il transmet l’information à l’utilisateur.', 5),
    ('b6dc8a43-4d13-5222-90ae-630e0e8594c4'::uuid, '84a12868-f4fb-58cf-84b8-4d7ba000c215'::uuid, 'Quel capteur mesure une distance sans contact ?', 'mcq', '["Le capteur à ultrasons","Le bouton-poussoir","Le capteur de température","Le fin de course"]'::jsonb, 0, 'Il mesure le temps de retour de l’écho.', 6),
    ('ee857f81-aa00-530a-b43f-2eb01375d2f2'::uuid, '84a12868-f4fb-58cf-84b8-4d7ba000c215'::uuid, 'Que doit garantir un objet connecté au-delà de sa fonction ?', 'mcq', '["La sécurité des données personnelles qu’il transmet","Une durée de vie illimitée","L’absence de programme interne","Une consommation nulle"]'::jsonb, 0, 'Un objet connecté mal protégé est une porte d’entrée pour le piratage.', 7),
    ('27e27ae7-bad9-560e-b24d-1c549545ccb7'::uuid, '84a12868-f4fb-58cf-84b8-4d7ba000c215'::uuid, 'Un bouton-poussoir est un actionneur.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est le plus simple des capteurs : il capte l’action de l’utilisateur.', 8),
    ('65c6cb90-aba3-55e4-812c-727e236d75b0'::uuid, '52dd6cd7-e87c-5197-876f-eb720d6fe097'::uuid, 'À quelle famille appartient le perçage ?', 'mcq', '["À l’enlèvement de matière","À la déformation","À l’ajout de matière","À l’assemblage"]'::jsonb, 0, 'Il produit des copeaux : de la matière est perdue.', 1),
    ('d4d2c9d6-3660-5619-a7b1-c63d4ab84ed5'::uuid, '52dd6cd7-e87c-5197-876f-eb720d6fe097'::uuid, 'À quelle famille appartient le pliage ?', 'mcq', '["À la déformation","À l’enlèvement de matière","À l’ajout de matière","À l’assemblage"]'::jsonb, 0, 'La matière change de forme sans être retirée.', 2),
    ('d0fa3306-78bb-5304-a486-8e42472e5e51'::uuid, '52dd6cd7-e87c-5197-876f-eb720d6fe097'::uuid, 'Comment appelle-t-on la fabrication par ajout de matière ?', 'mcq', '["L’impression 3D, ou fabrication additive","Le fraisage","L’emboutissage","Le rivetage"]'::jsonb, 0, 'La matière est déposée couche par couche.', 3),
    ('e2a663b0-52dd-58ab-956b-199a2497ca50'::uuid, '52dd6cd7-e87c-5197-876f-eb720d6fe097'::uuid, 'Quel assemblage permet de réparer et de recycler l’objet ?', 'mcq', '["Un assemblage démontable par vis ou clips","Une soudure","Un rivetage","Un collage"]'::jsonb, 0, 'Les assemblages non démontables sont définitifs.', 4),
    ('aaf68bbf-8b98-547e-a466-0c92c2461ae5'::uuid, '52dd6cd7-e87c-5197-876f-eb720d6fe097'::uuid, 'Que garantit une machine à commande numérique ?', 'mcq', '["La répétabilité et la précision des pièces produites","L’absence totale de déchets","Un coût nul","Une fabrication sans programme"]'::jsonb, 0, 'Elle exécute un programme issu du dessin numérique.', 5),
    ('5b696b6f-e1b5-5553-aff9-395c2b37418d'::uuid, '52dd6cd7-e87c-5197-876f-eb720d6fe097'::uuid, 'Quel procédé convient le mieux à une pièce unique de forme complexe ?', 'mcq', '["L’impression 3D","L’injection plastique","L’emboutissage","Le moulage en série"]'::jsonb, 0, 'Les procédés de série exigent un outillage coûteux.', 6),
    ('a228a856-5480-540c-92b4-28cfdd7a00a4'::uuid, '52dd6cd7-e87c-5197-876f-eb720d6fe097'::uuid, 'Quel critère décide principalement du choix d’un procédé ?', 'mcq', '["La quantité de pièces à produire","La couleur souhaitée","Le nom du fabricant","La date de livraison seule"]'::jsonb, 0, 'Matériau, forme, précision et coût interviennent également.', 7),
    ('b0c79650-d240-5fca-96ae-767e4fa53a89'::uuid, '52dd6cd7-e87c-5197-876f-eb720d6fe097'::uuid, 'La fabrication par déformation produit beaucoup de copeaux.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est l’enlèvement de matière qui en produit ; la déformation n’en perd pas.', 8),
    ('82ed01ec-f23c-5312-aac5-2c71c79d6871'::uuid, '9905e10b-14f3-57be-9261-54a75759f1a1'::uuid, 'Quand porte-t-on des lunettes de protection ?', 'mcq', '["Dès qu’une opération peut projeter des éclats","Uniquement lors des soudures","Seulement si la machine est bruyante","Uniquement en cas de produits chimiques"]'::jsonb, 0, 'Perçage, sciage et meulage projettent des particules.', 1),
    ('fc7ee1ab-3e49-5be6-969c-4418f2798308'::uuid, '9905e10b-14f3-57be-9261-54a75759f1a1'::uuid, 'Pourquoi ne porte-t-on pas de gants près d’une pièce en rotation ?', 'mcq', '["Parce qu’ils peuvent être happés par la pièce","Parce qu’ils réduisent la précision","Parce qu’ils s’usent trop vite","Parce qu’ils isolent du courant"]'::jsonb, 0, 'Le gant entraîne alors la main avec lui.', 2),
    ('f94d2861-77ce-5100-9e66-12b76e6a01e0'::uuid, '9905e10b-14f3-57be-9261-54a75759f1a1'::uuid, 'Que faut-il vérifier avant de démarrer une machine ?', 'mcq', '["Que les carters et protections sont en place","Que la salle est vide","Que la pièce est peinte","Que le programme est enregistré"]'::jsonb, 0, 'Et savoir où se trouve l’arrêt d’urgence.', 3),
    ('06ee41e6-d068-521c-94e5-00823ce2e904'::uuid, '9905e10b-14f3-57be-9261-54a75759f1a1'::uuid, 'Quand peut-on régler ou nettoyer une machine ?', 'mcq', '["Uniquement à l’arrêt complet","Pendant qu’elle tourne au ralenti","Dès que l’enseignant est présent","À tout moment avec des gants"]'::jsonb, 0, 'C’est la règle la plus enfreinte et la principale cause d’accidents.', 4),
    ('36776cde-7016-5778-82fb-6835c66e007e'::uuid, '9905e10b-14f3-57be-9261-54a75759f1a1'::uuid, 'Que signifie un pictogramme en triangle jaune ?', 'mcq', '["Un danger","Une obligation","Une interdiction","Une information de secours"]'::jsonb, 0, 'Le rond bleu signale une obligation, le rond rouge barré une interdiction.', 5),
    ('59795e5a-5c02-5415-b6d2-034272e0f9a6'::uuid, '9905e10b-14f3-57be-9261-54a75759f1a1'::uuid, 'Que signifie un pictogramme rond bleu ?', 'mcq', '["Une obligation, comme le port des lunettes","Un danger électrique","Une interdiction","Une issue de secours"]'::jsonb, 0, 'Le bleu impose un comportement ou un équipement.', 6),
    ('18531c4b-1622-5b09-9dff-ce501693d0c3'::uuid, '9905e10b-14f3-57be-9261-54a75759f1a1'::uuid, 'Que doit-on savoir avant de démarrer une machine ?', 'mcq', '["Où se trouve le bouton d’arrêt d’urgence","Le prix de la machine","Le nom du fabricant","La durée totale de l’opération"]'::jsonb, 0, 'Le chercher pendant l’incident est déjà trop tard.', 7),
    ('c256332d-4ad3-5632-9ff4-ee0253a9827d'::uuid, '9905e10b-14f3-57be-9261-54a75759f1a1'::uuid, 'Deux élèves peuvent travailler simultanément sur la même machine.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Un seul opérateur à la fois, et sans être distrait.', 8),
    ('f7a213b1-5da2-570f-ab63-0be5c55ff8e8'::uuid, '6d66a78e-0b9c-5257-ae17-9cb93155280f'::uuid, 'Qu’est-ce qu’un algorithme ?', 'mcq', '["Une suite d’instructions permettant d’obtenir un résultat","Un langage de programmation","Un composant électronique","Un logiciel de dessin"]'::jsonb, 0, 'Le programme en est la traduction pour la machine.', 1),
    ('79361743-2627-5eaa-b54d-b82b7952515a'::uuid, '6d66a78e-0b9c-5257-ae17-9cb93155280f'::uuid, 'Quelle structure permet d’exécuter des instructions seulement dans certains cas ?', 'mcq', '["La condition","La séquence","La boucle bornée","La variable"]'::jsonb, 0, 'Elle repose sur un test vrai ou faux.', 2),
    ('d23035fc-2980-5e43-af36-cc210218df87'::uuid, '6d66a78e-0b9c-5257-ae17-9cb93155280f'::uuid, 'Qu’est-ce qu’une boucle bornée ?', 'mcq', '["Une répétition dont on connaît le nombre de tours d’avance","Une répétition sans fin","Une répétition qui dépend d’un capteur","Une instruction unique"]'::jsonb, 0, '« Répéter 10 fois » en est une.', 3),
    ('a6eed7c9-55f4-5862-af2d-42a9a0f86f4c'::uuid, '6d66a78e-0b9c-5257-ae17-9cb93155280f'::uuid, 'À quoi sert une variable ?', 'mcq', '["À stocker une valeur susceptible de changer","À répéter des instructions","À comparer deux nombres","À commander un moteur"]'::jsonb, 0, 'Compteur, mesure, score : elle porte un nom et une valeur.', 4),
    ('ee317eab-0bcd-5d1c-827d-a63832be8aa2'::uuid, '6d66a78e-0b9c-5257-ae17-9cb93155280f'::uuid, 'Que fait l’opérateur logique « et » ?', 'mcq', '["Il exige que les deux conditions soient vraies","Il exige qu’au moins une condition soit vraie","Il inverse une condition","Il additionne deux nombres"]'::jsonb, 0, '« si porte fermée et code correct ».', 5),
    ('be06c7c1-48fe-510f-83e2-eaa708cde326'::uuid, '6d66a78e-0b9c-5257-ae17-9cb93155280f'::uuid, 'Qu’est-ce qu’une boucle infinie ?', 'mcq', '["Une boucle dont la condition d’arrêt n’est jamais atteinte","Une boucle qui s’exécute une seule fois","Une boucle qui contient une condition","Une boucle correctement bornée"]'::jsonb, 0, 'C’est l’erreur la plus fréquente du débutant.', 6),
    ('7aaff21b-6d33-5c0b-95ea-ba4fdd599bd3'::uuid, '6d66a78e-0b9c-5257-ae17-9cb93155280f'::uuid, 'Comment appelle-t-on la représentation graphique d’un algorithme ?', 'mcq', '["Un organigramme","Un tableau comparatif","Un diagramme des interacteurs","Un schéma cinématique"]'::jsonb, 0, 'Losanges pour les tests, rectangles pour les actions.', 7),
    ('13cc7fe4-11ce-52bc-b110-cd416f063cd4'::uuid, '6d66a78e-0b9c-5257-ae17-9cb93155280f'::uuid, 'Un algorithme dépend du langage de programmation utilisé.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il se traduit ensuite dans n’importe quel langage : c’est la logique qui compte.', 8),
    ('1308c327-88e2-58ad-a110-ef10d496bc19'::uuid, '1e568f9b-9059-5d45-a338-62f11544319e'::uuid, 'Quel est l’avantage principal de la programmation par blocs ?', 'mcq', '["Aucune faute de syntaxe n’est possible","Elle s’exécute plus vite","Elle permet des programmes plus longs","Elle est plus facile à partager par texte"]'::jsonb, 0, 'Les blocs incompatibles ne s’emboîtent tout simplement pas.', 1),
    ('07ac5c03-c7a1-5a7d-b717-71ef145155fc'::uuid, '1e568f9b-9059-5d45-a338-62f11544319e'::uuid, 'Quel logiciel relève de la programmation graphique ?', 'mcq', '["Scratch","Python","C++","JavaScript"]'::jsonb, 0, 'mBlock et Blockly également.', 2),
    ('aa52072d-840d-5dab-8431-4a41724e6a12'::uuid, '1e568f9b-9059-5d45-a338-62f11544319e'::uuid, 'Quelle est la principale difficulté de la programmation textuelle ?', 'mcq', '["La syntaxe, très stricte","L’impossibilité de faire des boucles","L’absence de variables","La lenteur d’exécution"]'::jsonb, 0, 'Un deux-points ou une indentation oubliés bloquent l’exécution.', 3),
    ('94dcfbfd-4d3c-55f6-b096-0adbe87f8d58'::uuid, '1e568f9b-9059-5d45-a338-62f11544319e'::uuid, 'En Python, que signale l’indentation ?', 'mcq', '["Ce qui appartient au bloc en cours","La fin du programme","Un commentaire","Une erreur de frappe"]'::jsonb, 0, 'Elle fait partie du langage, ce n’est pas une mise en forme.', 4),
    ('89b44ba3-c042-5aa8-ae71-3d385b99ab00'::uuid, '1e568f9b-9059-5d45-a338-62f11544319e'::uuid, 'Que change le passage des blocs au texte pour l’algorithme ?', 'mcq', '["Rien : séquence, condition, boucle et variable sont les mêmes","Tout : la logique doit être repensée","Les variables disparaissent","Les boucles deviennent impossibles"]'::jsonb, 0, 'Seule l’écriture change.', 5),
    ('3ff64077-fa4b-5fec-9899-f8d2b9f9cbf1'::uuid, '1e568f9b-9059-5d45-a338-62f11544319e'::uuid, 'Quel caractère termine en Python la ligne qui ouvre un bloc ?', 'mcq', '["Le deux-points","Le point-virgule","L’accolade","La parenthèse"]'::jsonb, 0, 'Il annonce le bloc indenté qui suit.', 6),
    ('ea43a6f1-d382-5d4e-8ab1-4f45661fa346'::uuid, '1e568f9b-9059-5d45-a338-62f11544319e'::uuid, 'Quel avantage la programmation textuelle offre-t-elle pour le travail en équipe ?', 'mcq', '["Le code se copie, se compare et se partage facilement","Elle se lit sans aucune formation","Elle interdit toute erreur","Elle ne nécessite pas d’ordinateur"]'::jsonb, 0, 'Un fichier texte se versionne, pas un assemblage de blocs.', 7),
    ('49956fa6-483b-5446-918a-117cd6f72689'::uuid, '1e568f9b-9059-5d45-a338-62f11544319e'::uuid, 'Un programme écrit en blocs ne peut pas piloter une carte programmable.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'mBlock et les environnements dérivés pilotent très bien une carte.', 8),
    ('fa8dcc01-9e33-5807-a121-762e2afd2a78'::uuid, '6bfd6eea-afa2-5af8-8569-c5789a1a9b71'::uuid, 'Que faut-il faire avant d’écrire le programme ?', 'mcq', '["Analyser le besoin et écrire l’algorithme","Choisir la couleur de l’interface","Acheter la carte programmable","Tester le programme"]'::jsonb, 0, 'L’algorithme se pense avant de toucher au clavier.', 1),
    ('5f6b97eb-4bea-5c84-af22-f0890da9d22a'::uuid, '6bfd6eea-afa2-5af8-8569-c5789a1a9b71'::uuid, 'Comment appelle-t-on la recherche et la correction des erreurs ?', 'mcq', '["Le débogage","La compilation","L’exécution","La documentation"]'::jsonb, 0, 'Elle alterne avec les tests jusqu’à conformité.', 2),
    ('d68848fd-2bb2-5dc0-a7e6-d6db98551f52'::uuid, '6bfd6eea-afa2-5af8-8569-c5789a1a9b71'::uuid, 'Quelle erreur empêche le programme de démarrer ?', 'mcq', '["L’erreur de syntaxe","L’erreur de logique","L’erreur d’ergonomie","L’erreur de câblage"]'::jsonb, 0, 'Le message d’erreur indique généralement la ligne fautive.', 3),
    ('40caa4a3-3b21-5d35-b74e-d95cab747c18'::uuid, '6bfd6eea-afa2-5af8-8569-c5789a1a9b71'::uuid, 'Quelle erreur est la plus difficile à détecter ?', 'mcq', '["L’erreur de logique","L’erreur de syntaxe","L’erreur d’orthographe dans un commentaire","L’erreur de nom de fichier"]'::jsonb, 0, 'Le programme s’exécute sans message, mais fait autre chose que prévu.', 4),
    ('e0ff57f2-6df3-52f6-a793-0d74e2ca6385'::uuid, '6bfd6eea-afa2-5af8-8569-c5789a1a9b71'::uuid, 'Qu’est-ce qu’un jeu d’essai ?', 'mcq', '["Un ensemble de cas de test préparés à l’avance","Une partie du programme non utilisée","Un jeu vidéo de démonstration","Une simulation graphique"]'::jsonb, 0, 'Un cas normal, un cas limite, un cas interdit.', 5),
    ('bcc0e0c0-0a56-56fd-abbd-d2b1ac83df9d'::uuid, '6bfd6eea-afa2-5af8-8569-c5789a1a9b71'::uuid, 'Pourquoi tester les cas limites ?', 'mcq', '["Parce que ce sont eux qui révèlent les défauts","Parce qu’ils sont plus rapides à exécuter","Parce qu’ils sont exigés par la norme","Parce qu’ils simplifient le code"]'::jsonb, 0, 'Un programme qui marche une fois n’est pas validé.', 6),
    ('f5413725-3494-5296-a5a0-8e3418bee1e7'::uuid, '6bfd6eea-afa2-5af8-8569-c5789a1a9b71'::uuid, 'Pourquoi commenter et nommer clairement ses variables ?', 'mcq', '["Pour rendre le programme modifiable par un autre, ou par soi plus tard","Pour accélérer l’exécution","Pour réduire la taille du fichier","Pour éviter les erreurs de syntaxe"]'::jsonb, 0, 'Un nom explicite vaut mieux qu’un commentaire.', 7),
    ('44133ec2-bf74-55db-a74f-46168645d208'::uuid, '6bfd6eea-afa2-5af8-8569-c5789a1a9b71'::uuid, 'Un programme sans message d’erreur fonctionne forcément correctement.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Une erreur de logique s’exécute sans rien signaler.', 8),
    ('f84fc647-cfad-5843-814c-a57ffcee567d'::uuid, '2fc4609f-5f7d-5d8b-8240-20f7b081947a'::uuid, 'Quelle différence y a-t-il entre une donnée et une information ?', 'mcq', '["L’information est une donnée interprétée dans un contexte","La donnée est toujours un texte","L’information est plus courte","Ce sont deux mots pour la même chose"]'::jsonb, 0, '« 18 » est une donnée ; « 18 °C dans le local » est une information.', 1),
    ('45afa45b-f570-5f64-9b48-65cc54f5f953'::uuid, '2fc4609f-5f7d-5d8b-8240-20f7b081947a'::uuid, 'Dans un tableau de données, que représente une ligne ?', 'mcq', '["Un enregistrement","Un champ","Une clé","Un type de données"]'::jsonb, 0, 'Les colonnes, elles, sont les champs.', 2),
    ('5f1798f1-3b2b-5a53-b1e8-17367964a68b'::uuid, '2fc4609f-5f7d-5d8b-8240-20f7b081947a'::uuid, 'À quoi sert une clé dans un tableau de données ?', 'mcq', '["À identifier chaque ligne sans ambiguïté","À trier les colonnes","À protéger le fichier","À convertir les unités"]'::jsonb, 0, 'Deux enregistrements ne peuvent pas partager la même clé.', 3),
    ('a1a7fe89-d83b-5043-816e-116430b7ed85'::uuid, '2fc4609f-5f7d-5d8b-8240-20f7b081947a'::uuid, 'Que fait un filtre sur un jeu de données ?', 'mcq', '["Il ne garde que les lignes vérifiant une condition","Il range les lignes par ordre croissant","Il calcule une moyenne","Il supprime les doublons automatiquement"]'::jsonb, 0, 'Le tri, lui, range sans rien enlever.', 4),
    ('b269d10c-ff14-57ee-b749-3f54ffd6b606'::uuid, '2fc4609f-5f7d-5d8b-8240-20f7b081947a'::uuid, 'Quel graphique convient pour représenter une évolution dans le temps ?', 'mcq', '["Une courbe","Un camembert","Un tableau croisé","Un diagramme de Venn"]'::jsonb, 0, 'Le camembert représente des parts d’un tout.', 5),
    ('10541ef8-8e23-5d12-8349-e72e2af2edb5'::uuid, '2fc4609f-5f7d-5d8b-8240-20f7b081947a'::uuid, 'Qu’est-ce qu’un fichier CSV ?', 'mcq', '["Un tableau en texte, avec des champs séparés par des virgules ou points-virgules","Une image compressée","Un programme exécutable","Un format de vidéo"]'::jsonb, 0, 'Simple et lisible par tous les tableurs.', 6),
    ('93928098-7d5e-578c-8458-8cd7ad679399'::uuid, '2fc4609f-5f7d-5d8b-8240-20f7b081947a'::uuid, 'Pourquoi vérifier les valeurs extrêmes d’un jeu de données ?', 'mcq', '["Parce qu’une valeur aberrante fausse tout le traitement","Parce qu’elles sont toujours fausses","Parce qu’elles ralentissent le calcul","Parce qu’elles doivent être supprimées systématiquement"]'::jsonb, 0, 'Une unité oubliée ou une saisie erronée se repère souvent là.', 7),
    ('b3e82416-0577-5f61-90a6-34e8fafb204c'::uuid, '2fc4609f-5f7d-5d8b-8240-20f7b081947a'::uuid, 'Le choix du type de graphique n’a aucune conséquence sur la lecture des données.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Une courbe raconte une évolution, un camembert une répartition : se tromper change le message.', 8),
    ('c09f3141-bb6d-5593-bc01-73c66aa8fc55'::uuid, '7d8eec64-79ae-5e66-8bca-184f7c2cb55e'::uuid, 'Qu’est-ce qu’un système d’information ?', 'mcq', '["L’ensemble matériel, logiciel, données, procédures et utilisateurs qui traite l’information","Un ordinateur puissant","Un logiciel de base de données","Un réseau de câbles"]'::jsonb, 0, 'Il collecte, stocke, traite et diffuse des données.', 1),
    ('abf143a1-56fd-5ecc-bd60-d459ba847705'::uuid, '7d8eec64-79ae-5e66-8bca-184f7c2cb55e'::uuid, 'Qu’est-ce que le stockage « dans le nuage » ?', 'mcq', '["Un stockage sur les serveurs d’un prestataire, accessible par Internet","Un stockage sans support physique","Un stockage sur une clé USB","Un stockage temporaire dans la mémoire vive"]'::jsonb, 0, 'Ce sont des centres de données bien réels, gourmands en énergie.', 2),
    ('00bc3664-b481-5ab5-8989-e09e02570143'::uuid, '7d8eec64-79ae-5e66-8bca-184f7c2cb55e'::uuid, 'À combien d’octets correspond 1 Go ?', 'mcq', '["10⁹ octets","10⁶ octets","10³ octets","10¹² octets"]'::jsonb, 0, 'Un film pèse quelques Go, une photo quelques Mo.', 3),
    ('8b5fa405-5cd4-5e76-b6ef-67baf186c8e8'::uuid, '7d8eec64-79ae-5e66-8bca-184f7c2cb55e'::uuid, 'Que dit la règle de sauvegarde 3-2-1 ?', 'mcq', '["3 copies, sur 2 supports différents, dont 1 hors du lieu principal","3 sauvegardes par jour pendant 2 semaines sur 1 disque","3 mots de passe, 2 comptes, 1 administrateur","3 To minimum, 2 disques, 1 serveur"]'::jsonb, 0, 'Et une sauvegarde jamais testée n’est pas une sauvegarde.', 4),
    ('4ce06acc-260e-5a79-a70a-68dde2b06869'::uuid, '7d8eec64-79ae-5e66-8bca-184f7c2cb55e'::uuid, 'À quoi sert le chiffrement des données ?', 'mcq', '["À les rendre illisibles sans la clé","À les compresser","À les sauvegarder automatiquement","À accélérer leur transfert"]'::jsonb, 0, 'C’est la protection de dernier recours en cas de vol.', 5),
    ('e43d7eea-12b3-53aa-8541-e2a3f56b997b'::uuid, '7d8eec64-79ae-5e66-8bca-184f7c2cb55e'::uuid, 'Que garantit le RGPD aux personnes ?', 'mcq', '["Un droit d’accès, de rectification et de suppression de leurs données","La gratuité des services en ligne","Un stockage illimité","L’anonymat total sur Internet"]'::jsonb, 0, 'Il impose aussi consentement, finalité déclarée et durée limitée.', 6),
    ('db93f380-5dea-5b5c-838d-053ed944f074'::uuid, '7d8eec64-79ae-5e66-8bca-184f7c2cb55e'::uuid, 'Quel est l’inconvénient principal d’un stockage uniquement local ?', 'mcq', '["Une panne, un vol ou un incendie fait tout disparaître","Il nécessite une connexion permanente","Il est toujours plus lent","Il est interdit par le RGPD"]'::jsonb, 0, 'D’où l’intérêt d’une copie hors du lieu principal.', 7),
    ('78677403-af98-5cae-911b-fef376ff9dab'::uuid, '7d8eec64-79ae-5e66-8bca-184f7c2cb55e'::uuid, 'Les données stockées dans le nuage ne se trouvent sur aucun support physique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elles sont sur les disques de centres de données bien réels.', 8),
    ('f455f7f2-741c-5f55-90b4-59ae5e230dde'::uuid, '02479358-a3cc-516f-8df9-4faf14c25c92'::uuid, 'Que désigne un LAN ?', 'mcq', '["Un réseau local, limité à un bâtiment ou un site","Le réseau mondial","Un réseau sans fil uniquement","Un protocole de sécurité"]'::jsonb, 0, 'Le WAN relie, lui, plusieurs sites.', 1),
    ('635993e2-185d-5cc5-b02a-d2944d0542ea'::uuid, '02479358-a3cc-516f-8df9-4faf14c25c92'::uuid, 'Quel équipement relie deux réseaux différents ?', 'mcq', '["Le routeur","Le switch","Le serveur","La carte réseau"]'::jsonb, 0, 'Le switch, lui, aiguille au sein d’un même réseau local.', 2),
    ('609ba2e2-6a20-5ee6-8ed5-37685ce0e807'::uuid, '02479358-a3cc-516f-8df9-4faf14c25c92'::uuid, 'À quoi sert une adresse IP ?', 'mcq', '["À identifier une machine sur le réseau","À chiffrer les données","À mesurer le débit","À stocker les fichiers"]'::jsonb, 0, 'Elle joue le rôle d’une adresse postale.', 3),
    ('ad82414d-1265-52b2-8b34-dfa9fc8e5c11'::uuid, '02479358-a3cc-516f-8df9-4faf14c25c92'::uuid, 'Que fait le DNS ?', 'mcq', '["Il traduit un nom de site en adresse IP","Il chiffre les communications","Il découpe les messages en paquets","Il distribue les adresses IP locales"]'::jsonb, 0, 'Sans lui, il faudrait retenir des suites de chiffres.', 4),
    ('ff686838-7d87-59a3-a82c-f66e0cdf9f19'::uuid, '02479358-a3cc-516f-8df9-4faf14c25c92'::uuid, 'Que signifie le S de HTTPS ?', 'mcq', '["L’échange est chiffré, donc sécurisé","Le site est un serveur","La connexion est plus rapide","Le site est officiel"]'::jsonb, 0, 'Le contenu échangé devient illisible pour un intercepteur.', 5),
    ('4e473a01-d279-590a-bbc0-bb1ef44fbea0'::uuid, '02479358-a3cc-516f-8df9-4faf14c25c92'::uuid, 'Comment un message circule-t-il sur Internet ?', 'mcq', '["Découpé en paquets numérotés, réassemblés à l’arrivée","D’un seul bloc, par un chemin unique","Uniquement par câble","Toujours par le même serveur central"]'::jsonb, 0, 'Si un chemin est coupé, les paquets passent par un autre.', 6),
    ('944942f3-e341-518d-882e-997b06523f3c'::uuid, '02479358-a3cc-516f-8df9-4faf14c25c92'::uuid, 'Quel équipement réunit routeur, switch, modem et point d’accès Wi-Fi ?', 'mcq', '["La box","Le serveur","Le commutateur seul","La carte mère"]'::jsonb, 0, 'C’est le boîtier présent dans la plupart des foyers.', 7),
    ('33b2cabe-f760-5b7d-84e6-885c3c99ef7b'::uuid, '02479358-a3cc-516f-8df9-4faf14c25c92'::uuid, 'Une connexion Wi-Fi est plus sûre qu’une connexion filaire.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le signal se diffuse dans l’air : il est plus exposé aux interceptions.', 8),
    ('b5df9ef7-62f0-581b-9019-c6886e763233'::uuid, 'a361a3fa-ab75-5e04-bbd7-6cf0a2042d46'::uuid, 'Qu’est-ce qu’un projet technique ?', 'mcq', '["Un ensemble d’actions coordonnées avec un objectif, un délai et des moyens limités","La fabrication d’un objet unique","Un dessin technique détaillé","Un cahier des charges"]'::jsonb, 0, 'Il se découpe en phases puis en tâches.', 1),
    ('347ecfc2-bd6a-586c-8322-52101d5710a3'::uuid, 'a361a3fa-ab75-5e04-bbd7-6cf0a2042d46'::uuid, 'Quelle est la première phase d’un projet ?', 'mcq', '["L’analyse du besoin et le cahier des charges","La réalisation du prototype","Les tests de validation","Le bilan"]'::jsonb, 0, 'On ne conçoit rien avant de savoir ce qui est demandé.', 2),
    ('dd7151fc-3758-5113-96f1-bd8efefd35f9'::uuid, 'a361a3fa-ab75-5e04-bbd7-6cf0a2042d46'::uuid, 'Que représente un diagramme de Gantt ?', 'mcq', '["Les tâches et leur durée dans le temps","Les fonctions de l’objet","Les interacteurs du système","Le budget du projet"]'::jsonb, 0, 'Chaque tâche est une barre horizontale.', 3),
    ('c5f30ffb-6aa2-53fb-a993-c4536e148ddc'::uuid, 'a361a3fa-ab75-5e04-bbd7-6cf0a2042d46'::uuid, 'Qu’est-ce qu’une antériorité entre deux tâches ?', 'mcq', '["Une tâche qui doit être finie avant qu’une autre commence","Une tâche facultative","Une tâche déjà réalisée dans un projet précédent","Une tâche sans responsable"]'::jsonb, 0, 'Elle contraint l’ordre du planning.', 4),
    ('db5dc2b9-b4aa-595a-8336-9fd6a1b9f206'::uuid, 'a361a3fa-ab75-5e04-bbd7-6cf0a2042d46'::uuid, 'Qu’est-ce que le chemin critique ?', 'mcq', '["La suite de tâches dont tout retard décale la fin du projet","La tâche la plus difficile","La tâche la plus coûteuse","Le trajet des pièces dans l’atelier"]'::jsonb, 0, 'Les autres tâches disposent d’une marge.', 5),
    ('01bf7a33-1e39-5d0e-87c8-548630e23bcf'::uuid, 'a361a3fa-ab75-5e04-bbd7-6cf0a2042d46'::uuid, 'À quoi sert une revue de projet ?', 'mcq', '["À faire le point en équipe et corriger la trajectoire","À valider le produit auprès du client final","À commander les matériaux","À rédiger la notice"]'::jsonb, 0, 'Elle se tient régulièrement, pas seulement à la fin.', 6),
    ('790670c8-2dd0-5259-a915-73fdedb1b752'::uuid, 'a361a3fa-ab75-5e04-bbd7-6cf0a2042d46'::uuid, 'Pourquoi documenter un essai raté ?', 'mcq', '["Pour éviter qu’un autre refasse la même erreur","Pour justifier le retard","Parce que la norme l’exige","Pour augmenter le nombre de pages du dossier"]'::jsonb, 0, 'Un essai raté documenté vaut mieux qu’un succès inexpliqué.', 7),
    ('08098fe2-4025-5df7-8f8d-ea23ba219227'::uuid, 'a361a3fa-ab75-5e04-bbd7-6cf0a2042d46'::uuid, 'Toutes les tâches d’un projet doivent se dérouler l’une après l’autre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Beaucoup se mènent en parallèle : c’est ce que montre le diagramme de Gantt.', 8),
    ('6e2f8aa4-4d57-56a1-b064-8f0e79479de6'::uuid, '00feabf3-2c17-5a23-975f-c845aa78ca3a'::uuid, 'Qu’est-ce qu’un croquis ?', 'mcq', '["Un dessin à main levée, rapide, pour fixer une idée","Un dessin normalisé à l’échelle","Un schéma électrique","Un modèle 3D simplifié"]'::jsonb, 0, 'Ni à l’échelle, ni normalisé : c’est ce qui le rend rapide.', 1),
    ('330937b4-8a3f-5aa9-9fef-5c440ca7bf02'::uuid, '00feabf3-2c17-5a23-975f-c845aa78ca3a'::uuid, 'Que représente un schéma cinématique ?', 'mcq', '["Les liaisons entre pièces et les mouvements possibles","Le circuit électrique","Les dimensions réelles de l’objet","Le planning du projet"]'::jsonb, 0, 'Il décrit le fonctionnement mécanique, pas la forme.', 2),
    ('285a26a5-84b1-5f41-8716-7e2b7e9a6cf2'::uuid, '00feabf3-2c17-5a23-975f-c845aa78ca3a'::uuid, 'Que signifie une échelle 1:2 ?', 'mcq', '["Le dessin est deux fois plus petit que l’objet réel","Le dessin est deux fois plus grand","Le dessin est à taille réelle","L’objet mesure 2 mm"]'::jsonb, 0, 'Une échelle 2:1 serait deux fois plus grande que le réel.', 3),
    ('c5093883-12b3-5be3-be75-f004c10a59b8'::uuid, '00feabf3-2c17-5a23-975f-c845aa78ca3a'::uuid, 'Que donne la cotation d’un dessin technique ?', 'mcq', '["Les dimensions réelles de l’objet, en millimètres","La liste des matériaux","Le nom du concepteur","Le prix de fabrication"]'::jsonb, 0, 'Elle rend le dessin exploitable par le fabricant.', 4),
    ('520aea6f-6c56-547e-82a7-38208d01e2db'::uuid, '00feabf3-2c17-5a23-975f-c845aa78ca3a'::uuid, 'Que signifie un trait interrompu sur un dessin technique ?', 'mcq', '["Une arête cachée","Une arête vue","Un axe de symétrie","Une cote"]'::jsonb, 0, 'Le trait continu fort marque les arêtes vues.', 5),
    ('d4351169-3324-5b44-be9d-91719423e14f'::uuid, '00feabf3-2c17-5a23-975f-c845aa78ca3a'::uuid, 'Que permet la modélisation 3D avant toute fabrication ?', 'mcq', '["Simuler les mouvements et détecter les interférences entre pièces","Réduire le prix des matériaux","Supprimer les tests de validation","Éviter le cahier des charges"]'::jsonb, 0, 'Elle permet aussi d’exporter vers une imprimante 3D ou une MOCN.', 6),
    ('5b30f0c9-a59d-5078-852c-9e36cfe3105a'::uuid, '00feabf3-2c17-5a23-975f-c845aa78ca3a'::uuid, 'Quelle représentation sert à faire fabriquer une pièce ?', 'mcq', '["Le dessin technique coté et à l’échelle","Le croquis à main levée","Le schéma de principe","Le diagramme de Gantt"]'::jsonb, 0, 'C’est un document contractuel entre concepteur et fabricant.', 7),
    ('1e54a0ef-d5e1-570d-95c5-df09161e3b39'::uuid, '00feabf3-2c17-5a23-975f-c845aa78ca3a'::uuid, 'Un croquis doit toujours être réalisé à l’échelle.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est justement sa liberté qui en fait un outil de recherche rapide.', 8),
    ('2bb98ff0-acbd-53ee-b142-cb5809df7b78'::uuid, '4b158890-abe1-5226-bd1e-84e771f004e7'::uuid, 'Par quoi commence toute démarche de conception ?', 'mcq', '["L’analyse du besoin et le cahier des charges","Le choix du matériau","La fabrication du prototype","La rédaction de la notice"]'::jsonb, 0, 'On ne conçoit pas avant de savoir ce qui est demandé.', 1),
    ('13019f6e-2159-5231-9c7e-f4469197204d'::uuid, '4b158890-abe1-5226-bd1e-84e771f004e7'::uuid, 'Pourquoi chercher plusieurs solutions avant de choisir ?', 'mcq', '["Parce qu’une seule idée n’est pas un choix","Pour allonger la durée du projet","Parce que la norme l’impose","Pour utiliser tous les matériaux disponibles"]'::jsonb, 0, 'La comparaison est ce qui rend le choix justifiable.', 2),
    ('82e63254-2647-59e0-a025-111f21ae0dda'::uuid, '4b158890-abe1-5226-bd1e-84e771f004e7'::uuid, 'Qu’est-ce qu’une nomenclature ?', 'mcq', '["La liste des pièces avec quantités et références","Le planning du projet","La liste des utilisateurs","Le nom commercial de l’objet"]'::jsonb, 0, 'Elle accompagne les dessins de conception.', 3),
    ('22995d37-0386-55fa-ab3b-a05483709571'::uuid, '4b158890-abe1-5226-bd1e-84e771f004e7'::uuid, 'Qu’est-ce qu’une gamme de fabrication ?', 'mcq', '["L’ordre des opérations pour réaliser une pièce","La gamme de prix du produit","La liste des fournisseurs","L’ensemble des variantes du produit"]'::jsonb, 0, 'Elle précise machines, outils et règles de sécurité.', 4),
    ('eb14c8c1-83c5-5eb6-b597-c58d5095152d'::uuid, '4b158890-abe1-5226-bd1e-84e771f004e7'::uuid, 'Pourquoi contrôler les pièces au fur et à mesure ?', 'mcq', '["Parce qu’un défaut détecté tôt coûte beaucoup moins cher","Pour occuper le temps d’attente","Parce que le client l’exige","Pour éviter la nomenclature"]'::jsonb, 0, 'Un assemblage terminé avec une pièce hors cote est à refaire entièrement.', 5),
    ('2ebaec20-0f3d-5ff0-8bc0-c963b52870b4'::uuid, '4b158890-abe1-5226-bd1e-84e771f004e7'::uuid, 'Que signifie une démarche itérative ?', 'mcq', '["Elle revient en arrière quand un test échoue ou qu’une contrainte change","Elle suit un ordre strict et immuable","Elle se fait sans tests","Elle ne concerne que la fabrication"]'::jsonb, 0, 'Un test raté renvoie à la conception.', 6),
    ('9c33631a-6eca-5617-ba65-f3a9d3fe9af0'::uuid, '4b158890-abe1-5226-bd1e-84e771f004e7'::uuid, 'Que contient la documentation finale d’un projet ?', 'mcq', '["Dossier de conception, plans, nomenclature, programme et notice","Uniquement la facture des matériaux","Uniquement les photos de l’objet","Uniquement le cahier des charges"]'::jsonb, 0, 'Elle prouve la maîtrise de la démarche autant que l’objet lui-même.', 7),
    ('24b8cd77-bb62-5375-83c7-af06f7623b5b'::uuid, '4b158890-abe1-5226-bd1e-84e771f004e7'::uuid, 'La démarche de conception se déroule toujours en ligne droite.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est itérative : on revient en arrière dès qu’un test ou une contrainte l’impose.', 8),
    ('57cdb97c-8f28-5b4d-be9d-cd0250a2ea33'::uuid, '1daa75ee-9f07-578f-b265-ac2b92d29317'::uuid, 'Quelle différence y a-t-il entre tester et valider ?', 'mcq', '["Tester mesure, valider compare la mesure à l’exigence","Tester compare, valider mesure","Ce sont deux mots pour la même chose","Tester concerne le prototype, valider la série"]'::jsonb, 0, 'La validation conclut : conforme ou non conforme.', 1),
    ('c6005069-fb22-5d3b-83fc-a4d5792c1516'::uuid, '1daa75ee-9f07-578f-b265-ac2b92d29317'::uuid, 'Quel essai consiste à tirer sur une pièce jusqu’à la rupture ?', 'mcq', '["L’essai de traction","L’essai de compression","L’essai de flexion","L’essai de torsion"]'::jsonb, 0, 'La compression, elle, écrase la pièce.', 2),
    ('19c3156e-a2cc-5a18-9ef3-d285e0ba5314'::uuid, '1daa75ee-9f07-578f-b265-ac2b92d29317'::uuid, 'Quel essai révèle une rupture due à la répétition d’un effort ?', 'mcq', '["L’essai de fatigue","L’essai de traction","L’essai de dureté","L’essai d’étanchéité"]'::jsonb, 0, 'Beaucoup de pièces cassent par répétition, pas par excès d’effort.', 3),
    ('36660269-b5b1-526b-8734-4dc1138435e6'::uuid, '1daa75ee-9f07-578f-b265-ac2b92d29317'::uuid, 'Que doit contenir un protocole d’essai ?', 'mcq', '["La grandeur mesurée, l’instrument, les conditions et le mode opératoire","Uniquement le résultat final","Le nom du fabricant","Le prix de l’objet testé"]'::jsonb, 0, 'C’est ce qui rend l’essai reproductible.', 4),
    ('1fad542e-22ba-57a7-a85a-36d7d5aa35ef'::uuid, '1daa75ee-9f07-578f-b265-ac2b92d29317'::uuid, 'Que calcule une simulation numérique sur un modèle 3D ?', 'mcq', '["Les contraintes, les déformations et les zones de rupture probables","Le prix de revient","La durée de fabrication","Le nombre d’utilisateurs"]'::jsonb, 0, 'Elle permet d’essayer plusieurs formes sans rien fabriquer.', 5),
    ('5d217d78-327e-5207-b860-b9075f8ad4d1'::uuid, '1daa75ee-9f07-578f-b265-ac2b92d29317'::uuid, 'Quelle est la limite de la simulation numérique ?', 'mcq', '["Elle repose sur des hypothèses et ne remplace pas l’essai réel","Elle est toujours plus lente qu’un essai","Elle ne fonctionne que sur les métaux","Elle ne donne aucun résultat chiffré"]'::jsonb, 0, 'Un modèle est une représentation, pas la réalité.', 6),
    ('b92c4be1-4c80-50eb-8932-bd91b020f8bd'::uuid, '1daa75ee-9f07-578f-b265-ac2b92d29317'::uuid, 'Que fait-on en cas de non-conformité ?', 'mcq', '["On revient à la conception pour corriger","On ajuste le cahier des charges au résultat obtenu","On refait le même essai jusqu’à réussir","On livre l’objet en le signalant"]'::jsonb, 0, 'C’est le retour de boucle de la démarche itérative.', 7),
    ('b9375b73-bb66-540b-a2af-17dc27bf4845'::uuid, '1daa75ee-9f07-578f-b265-ac2b92d29317'::uuid, 'Un résultat d’essai se suffit à lui-même, sans ses conditions.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '« Il tient 40 kg » ne veut rien dire sans savoir comment la charge a été appliquée.', 8),
    ('318fa6b9-c4ad-5ac3-9907-aff50afde484'::uuid, '101cfd87-5688-56ec-bcfe-2ec7896cbf68'::uuid, 'Qu’est-ce qu’un prototype ?', 'mcq', '["Un premier exemplaire fabriqué pour vérifier une solution","Le produit final vendu au client","Un dessin en trois dimensions","Un cahier des charges illustré"]'::jsonb, 0, 'Il sert à apprendre avant de produire.', 1),
    ('7bf2fc7d-e041-5859-880d-a7aab4c1e914'::uuid, '101cfd87-5688-56ec-bcfe-2ec7896cbf68'::uuid, 'Qu’est-ce qu’une maquette ?', 'mcq', '["Un modèle à l’échelle, non fonctionnel, qui montre la forme","Un prototype qui fonctionne","Le premier exemplaire de la série","Un dessin technique coté"]'::jsonb, 0, 'Elle sert à juger l’encombrement et l’aspect.', 2),
    ('8f51f2a9-4576-58ad-97ff-7475823e90a1'::uuid, '101cfd87-5688-56ec-bcfe-2ec7896cbf68'::uuid, 'Qu’est-ce qu’un prototype fonctionnel ?', 'mcq', '["Un exemplaire qui fonctionne, avec des matériaux différents de la série","Une maquette en carton","Le produit final","Un modèle numérique"]'::jsonb, 0, 'Il valide la solution, pas encore le procédé de fabrication.', 3),
    ('93638f45-3021-5ba3-9874-7e8bbf384253'::uuid, '101cfd87-5688-56ec-bcfe-2ec7896cbf68'::uuid, 'Quel moyen permet de fabriquer rapidement une pièce de forme complexe ?', 'mcq', '["L’impression 3D","Le moulage par injection","L’emboutissage","Le forgeage"]'::jsonb, 0, 'Une pièce à la fois, en quelques heures.', 4),
    ('7ead8df6-8962-5f5d-ab43-8f0a62ec2435'::uuid, '101cfd87-5688-56ec-bcfe-2ec7896cbf68'::uuid, 'Pourquoi montrer un prototype à l’utilisateur ?', 'mcq', '["Parce que son avis sur un objet réel est bien plus riche que sur un dessin","Pour lui faire signer le cahier des charges","Pour fixer le prix de vente","Parce que la norme l’impose"]'::jsonb, 0, 'On y détecte des problèmes d’usage invisibles sur le papier.', 5),
    ('5f3d7437-8a77-53c4-b6a4-4d773f8ac223'::uuid, '101cfd87-5688-56ec-bcfe-2ec7896cbf68'::uuid, 'Que signifie itérer en prototypage ?', 'mcq', '["Enchaîner prototype, test, analyse, modification et nouveau prototype","Fabriquer plusieurs exemplaires identiques","Répéter le même essai","Produire en série"]'::jsonb, 0, 'Chaque tour coûte du temps mais en fait gagner beaucoup plus.', 6),
    ('ebcf36ff-ee7c-536d-81bc-576fcc292a0a'::uuid, '101cfd87-5688-56ec-bcfe-2ec7896cbf68'::uuid, 'Pourquoi une erreur détectée sur un prototype coûte-t-elle peu ?', 'mcq', '["Parce qu’elle n’affecte qu’un exemplaire, pas toute une production","Parce que le prototype est gratuit","Parce qu’elle est toujours mineure","Parce qu’elle ne nécessite aucune correction"]'::jsonb, 0, 'La même erreur sur dix mille exemplaires vendus est cent fois plus coûteuse.', 7),
    ('d33bcfad-24da-579a-861f-c755f238114b'::uuid, '101cfd87-5688-56ec-bcfe-2ec7896cbf68'::uuid, 'Un prototype qui ne fonctionne pas rend le projet inutile.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un test qui a donné son résultat : le vrai risque serait de produire sans avoir rien testé.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('technologie');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('technologie')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 335 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 335 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
